const r = $json || {};
const errors = [];
const text = (r.input ?? '').toString();
if (!text.trim()) errors.push('input_required');
if (text.length > 32000) errors.push('input_too_long');

const rand = () => Math.random().toString(16).slice(2, 10);
const normalized = {
  requestId: r.requestId || ('req-' + Date.now().toString(16) + '-' + rand()),
  traceId: r.traceId || ('trace-' + Date.now().toString(16) + '-' + rand()),
  sessionId: r.sessionId || ('session-' + rand()),
  userId: r.userId || 'anonymous',
  input: text.trim(),
  intent: r.intent || '',
  metadata: r.metadata || {},
  schemaVersion: '1.0',
  receivedAt: new Date().toISOString(),
};

return {
  valid: errors.length === 0,
  errors,
  request: normalized,
  schema: 'common.request.v1',
};
